-- ============================================================
-- VIII. PLAGUE GARDEN SECT (毒花谷宗)
-- ============================================================

update wf_user.my_frames
set
    cultivation_color    = '#7FB800',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Tang Sect Ichor',
    cultivation_art      = 'Tang Sect Spore Dao of the Serpent Contagion',
    cultivation_doctrine = $doc$Saryn Prime's name derives from Sarin -- the nerve agent -- and her cultivation practice makes no attempt to soften this lineage. She is the Tang Sect's most complete expression: the cultivator whose art is not fighting but infection, not combat but cascade. Spores do not deal damage. They establish a network -- the Serpent Contagion's opening move, seeding the battlefield with biological infrastructure that will do the work while Saryn Prime attends to other matters. Molt does not provide a decoy. It sheds -- the serpent skin-shedding technique that refreshes the Spore network's physical anchor while leaving enemies confused about which body to target. Toxic Lash does not add a damage type to melee. It converts Saryn Prime's physical contact into a vector, because in the Tang Sect tradition, every surface the practitioner touches is a potential transmission point. Miasma does not deal damage across the field. It concludes the Serpent Contagion argument: the moment when the Spore network reaches critical density and the Tang Sect's fundamental premise becomes undeniable -- that you were already infected before you realized the fight had started. Saryn Prime does not clear rooms. She cultivates them.$doc$
where build_title = 'Tang Sect Ichor';

update wf_user.my_frames
set
    cultivation_color    = '#7A1A2C',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Infested Monarch',
    cultivation_art      = 'Infested Cordyceps Dao of the Mutating Host',
    cultivation_doctrine = $doc$Nidus Prime's Latin name means nest, and the Infested Cordyceps Dao treats this etymology as a complete mission statement. He is not a Warframe who uses Infested abilities. He is a Warframe who has decided to become the Helminth's most cooperative host -- the cultivator who understood that the Infested are not a disease to be resisted but a cultivation partner to be negotiated with. Virulence does not deal damage. It propagates -- the opening note of the Mutation Stack economy that is Nidus Prime's entire cultivation practice. Larva does not crowd-control. It centralizes, pulling the available biomass into a configuration that serves the nest's needs. Parasitic Link does not buff an ally or drain an enemy. It conducts the Helminth compact: a temporary merger between Nidus Prime's Mutation Stack economy and another body's biology, the Infested Monarch demonstrating that the nest boundary is negotiable. Ravenous does not heal or generate maggots. It cultivates -- the Cordyceps network spreading outward from Nidus Prime's position, converting the local terrain into something that prefers his presence. The Infested Monarch does not grow stronger by fighting. He grows stronger by remaining in the nest long enough for the nest to grow around him.$doc$
where build_title = 'Infested Monarch';

update wf_user.my_frames
set
    cultivation_color    = '#1A0F1F',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Spiderwoman',
    cultivation_art      = 'Jorogumo Silk Dao of the Venomed Gown',
    cultivation_doctrine = $doc$Oraxia's cultivation lineage is the Jorogumo -- the Japanese spider-woman demon of Edo-period folklore, a creature that appears as a beautiful woman to lure victims before revealing its true form. The qipao gown, the web-cocoon architecture, the Toxin progenitor role in the Plague Garden Sect: all of these point to a cultivation practice whose central technique is the gap between appearance and reality. The Venomed Gown Dao does not teach straightforward toxin cultivation. It teaches the ambush -- the principle that the most efficient poison delivery system is the one the target helps you deploy because they do not recognize it as a threat until it has already worked. Oraxia's silk does not restrain. It invites -- targets walking into the web because the Jorogumo has made the web look like the safest place in the room. Her toxin does not attack. It concludes a hospitality that was always hostile. In the Plague Garden Sect, Saryn Prime is the open war and Oraxia is the closed door that you walked through because it was open when you arrived.$doc$
where build_title = 'Spiderwoman';

update wf_user.my_frames
set
    cultivation_color    = '#FF6B6B',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Nukkulaelae',
    cultivation_art      = 'Mycelium Sprout Dao of the False Morel',
    cultivation_doctrine = $doc$Nokko's name derives from kinoko (Japanese: mushroom) and Nukkulaelae Atoll -- a Pacific island ecosystem whose coral network functions like a mycelium web, connecting disparate surface features through an invisible underground intelligence. She is the Plague Garden Sect's youngest disciple and its most ecologically precise one: where Saryn Prime cultivates plague and Nidus Prime cultivates nest, Nokko cultivates network. Her mushrooms are named after real toxic fungi -- False Morels, Stinkhorns, Death Caps -- and her cultivation practice is the mycelium network's fundamental principle: that the most powerful defense is one that the attacker cannot see because it lives underground. The False Morel Dao teaches that toxin does not need to be dramatic. It needs to be pervasive. The mushroom does not fight the forest. It IS the forest's communication network, its immune system, its memory -- and everything that walks through the forest walks through the mushroom whether it knows it or not. Nokko is the Sect's proof that ecological integration is the ultimate form of toxin cultivation.$doc$
where build_title = 'Nukkulaelae';

update wf_user.my_frames
set
    cultivation_color    = '#D4D700',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Reactor Apostle',
    cultivation_art      = 'Atomic Brutalist Dao of the Crucible Core',
    cultivation_doctrine = $doc$The Plague Garden Sect cultivates toxin through living vectors - spores, mycelium, venom. Qorvex is the sect''s only inorganic disciple, and its most dangerous. Albrecht Entrati did not build him to poison; he built him to contain. The Chyrinka Pillars are dosimetry made architectural - radiation measured, concentrated, and discharged as structural theology. Disometric Guard does not defend; it converts incoming damage into outgoing Radiation, because a reactor does not absorb energy, it processes it. Fused Reservoir does not debuff enemies. It saturates -- the Atomic Brutalist Dao's central technique: creating zones of concentrated radioactive presence that alter the physics of everything inside them. The Crucible at his core is not a weapon. It is a power plant that has decided the most efficient energy output is enemy dissolution. Qorvex is the proof that toxin does not require biology to reach its highest expression -- it requires only a source, a medium, and a cultivator willing to become the reactor. The Reactor Apostle does not irradiate his enemies. He irradiates his environment, and his enemies happen to be standing in it.$doc$
where build_title = 'Reactor Apostle';

update wf_user.my_frames
set
    cultivation_color    = '#4A3728',
    cultivation_school   = 'Plague Garden Sect',
    cultivation_identity = 'Alchemist Supreme',
    cultivation_art      = 'Elemental Transmutation Dao of the Void Alchemist',
    cultivation_doctrine = $doc$Lavos Prime is the Plague Garden Sect's alchemist -- the cultivator whose art is not poison as a fixed state but poison as a transmutation process, the medieval-alchemical tradition of elemental conversion applied to Warframe combat. His passive does not charge abilities. It charges elements -- Lavos Prime cycling through the four classical elements continuously, every melee hit loading the next ability with whatever the alchemical cycle has currently produced. Vial Rush does not deal damage. It seeds -- leaving elemental residue across the terrain that subsequent abilities will interact with. Ophidian Bite does not transmute enemies. It applies the Void Alchemist's fundamental operation: the forced elemental conversion of a living body, demonstrating that the alchemical tradition's promise of lead-into-gold applies equally to flesh-into-something-more-useful. Transmutation Probe does not combine elements. It conducts the Dao's central teaching -- that no element in the Plague Garden Sect's toolkit is the final form, that every toxic state is a precursor to a more refined toxic state. Metamorphosis does not buff. It completes the alchemical cycle, the Void Alchemist momentarily embodying the Great Work -- the philosopher's stone of combat cultivation, the brief instant when every element is simultaneously available and the transmutation is total.$doc$
where build_title = 'Alchemist Supreme';


-- ============================================================
-- IX. TIDAL ABYSS CONFRATERNITY (瀚海宗)
-- ============================================================

update wf_user.my_frames
set
    cultivation_color    = '#1B6E8C',
    cultivation_school   = 'Tidal Abyss Confraternity',
    cultivation_identity = 'Tidal Conqueror',
    cultivation_art      = 'Kraken Pirate Dao of the Davy Tempest',
    cultivation_doctrine = $doc$Hydroid Prime's cultivation lineage runs through Davy Jones, the Kraken, and every sea-pirate tradition that understood the ocean not as an obstacle but as a dominion. The Tidal Abyss Confraternity was founded on this understanding: that water is not a medium but a sovereign territory, and the cultivator who has claimed it has access to a form of authority that land-based practitioners cannot contest. Tempest Barrage does not bombard from above. It calls -- the pirate king signaling his fleet, except the fleet is made of water and it comes from underneath. Tidal Surge does not provide mobility. It conducts the Kraken Pirate Dao's central movement principle: that the cultivator who is made of water cannot be stopped by obstacles, only redirected. Undertow does not create a puddle. It opens a portal to the Tidal Abyss -- the deep-water dominion that Hydroid Prime rules, into which enemies disappear and from which they do not return in their original form. Tentacle Swarm does not spawn crowd control. It calls the Kraken -- the apex predator of the Tidal Abyss Confraternity's cosmology, the thing that waits at the bottom of every ocean for a pirate king worthy of summoning it.$doc$
where build_title = 'Tidal Conqueror';

update wf_user.my_frames
set
    cultivation_color    = '#A8E6FF',
    cultivation_school   = 'Tidal Abyss Confraternity',
    cultivation_identity = 'Snow Monarch',
    cultivation_art      = 'Eternal Winter Dao of the Snow Globe Sovereign',
    cultivation_doctrine = $doc$Frost Prime is the Tidal Abyss Confraternity's emperor of stillness -- the Jack-Frost/Jotunn elemental cultivator who has understood that the most powerful defensive technique in the Confraternity is not water's fluidity but water's terminal state: the ice that does not move, the snow that does not yield, the glacier that defeats mountains not through force but through patience measured in geological time. Freeze does not immobilize. It concludes a thermal argument -- the Snow Monarch establishing that his temperature is the local temperature. Snow Globe does not create a defensive dome. It creates a sovereign territory -- an enclosed space where Frost Prime's physics apply, where the Eternal Winter Dao's central teaching is environmental law: nothing moves faster than the Snow Globe Sovereign permits. Avalanche does not deal damage. It expresses the Confraternity's most complete defensive offense: stripping armor with the casualness of something that has never needed armor because it IS the cold, and dealing damage as the byproduct of a temperature assertion. The Snow Monarch does not fight enemies. He creates conditions where they cannot fight him.$doc$
where build_title = 'Snow Monarch';

update wf_user.my_frames
set
    cultivation_color    = '#F5F5F0',
    cultivation_school   = 'Tidal Abyss Confraternity',
    cultivation_identity = 'Crystal Sentinel',
    cultivation_art      = 'Shattered Glass Dao of the Vitrified Martyr',
    cultivation_doctrine = $doc$Gara Prime did not choose the Tidal Abyss Confraternity's crystalline branch. She became it -- a warrior who shattered herself against a Sentient to stop the invasion, whose sacrifice created the Eidolons as the crystallized echo of her final act. The Shattered Glass Dao does not pretend this history is comfortable. It treats it as the cultivation practice's load-bearing structure: that the most powerful glass was once whole, and broke for a reason that mattered more than staying whole. Shattered Lash does not deal damage. It extends Gara Prime's shattered self as a weapon, the Vitrified Martyr making her own fragmentation into an attack vector. Splinter Storm does not provide a damage buff. It conducts the Dao's central teaching: that breaking is a condition, not an ending, and the cultivator who has already broken can make breaking work for her. Spectrorage does not crowd control. It creates a mirror maze -- the Shattered Glass Dao's hall of reflections, where every enemy sees itself at the moment of maximum vulnerability. Mass Vitrify does not crystallize terrain. It remembers -- the moment of Gara Prime's original sacrifice, the wall of glass she became to stop what was coming, here reconstructed around whatever needs stopping now.$doc$
where build_title = 'Crystal Sentinel';

update wf_user.my_frames
set
    cultivation_color    = '#FFB000',
    cultivation_school   = 'Tidal Abyss Confraternity',
    cultivation_identity = 'Geode',
    cultivation_art      = 'Geode Aurora Dao of the Prismatic Vow',
    cultivation_doctrine = $doc$Citrine's cultivation lineage is the merchant's stone -- the yellow quartz that commercial tradition associates with abundance, clarity, and the transformation of raw material into refined value. She is the Tidal Abyss Confraternity's crystallographer: where Gara Prime works with shattered glass and Frost Prime works with ice, Citrine works with the crystal in its most precise form -- the geological structure that took millennia to achieve its lattice and now refracts everything that passes through it into its component frequencies. Her lore establishes that she fossilized her lovers Belric and Rania in crystal during the Old War, the Prismatic Vow being the cultivation technique she used to preserve what she could not save. Crystallize does not crowd control. It preserves -- the Geode Aurora Dao's foundational operation, applying the same technique to enemies that Citrine once applied to love. Fractured Blast does not detonate crystals. It harvests -- the prismatic conversion of crystalline structure into applicable force. Preserving Shell does not provide damage reduction. It vows -- the Prismatic Vow renewed, the crystal lattice extended outward to include whoever Citrine has decided deserves preservation this encounter. Dazzling Vow does not debuff enemies. It refracts them -- the four-element prism expressing the Geode Aurora Dao's highest teaching: that the cultivator who can split any force into its components can also reconstruct any force from its components.$doc$
where build_title = 'Geode';

update wf_user.my_frames
set
    cultivation_color    = '#C0C0C0',
    cultivation_school   = 'Tidal Abyss Confraternity',
    cultivation_identity = 'Chain Empress',
    cultivation_art      = 'Silver Chain Huntress Dao of the Mistress and Beast',
    cultivation_doctrine = $doc$Khora Prime's cultivation lineage runs through Diana the huntress and the dominatrix archetype simultaneously -- a combination that the Silver Chain Huntress Dao treats not as a contradiction but as a unity, because both traditions are ultimately about the same thing: the precise control of power through the management of tension. Her companion Venari is not a pet. She is the soul of Ballas's lover, housed in a kavat's body by Orokin technology, which makes Khora Prime's relationship with Venari simultaneously a hunting partnership and a haunted vigil. Whipclaw does not deal damage. It conducts -- the crack of the silver chain across the battlefield, the sound that both the Diana and dominatrix traditions recognize as the declaration of authority. Ensnare does not crowd control. It applies the Chain Empress's fundamental technique: the whip that does not hurt but cannot be ignored, the restraint that is more complete than any barrier. Venari does not fight alongside Khora Prime. She completes her -- the Beast to the Mistress, the kavat soul to the chain-wielding hunter, the two halves of a cultivation practice that has always understood that the most sophisticated combat doctrine is the one conducted between two entities who have learned to operate as one.$doc$
where build_title = 'Chain Empress';


-- ============================================================
-- X. COSMIC ANTIMATTER COUNCIL (虚星宫)
-- ============================================================

update wf_user.my_frames
set
    cultivation_color    = '#FF1493',
    cultivation_school   = 'Cosmic Antimatter Council',
    cultivation_identity = 'Ton-618',
    cultivation_art      = 'Black Hole Antimatter Dao of the Molecular Empress',
    cultivation_doctrine = $doc$Nova Prime is named after the stellar event that occurs when a white dwarf accumulates enough mass to trigger runaway nuclear fusion -- a star that becomes temporarily brighter than its entire galaxy before collapsing into something denser and stranger than it was. The Black Hole Antimatter Dao takes this etymology as a mission statement. Null Star does not orbit. It accumulates -- Nova Prime gathering the antimatter that her Cosmic Antimatter Council cultivation produces as a byproduct of existing, storing it as orbiting damage reduction that also happens to deal molecular deconstruction on contact. Wormhole does not provide mobility. It conducts Einstein-Rosen bridge engineering on a tactical scale -- the Molecular Empress creating stable spacetime shortcuts that the Antimatter Dao recognizes as one of the Cosmic Antimatter Council's signature techniques. Antimatter Drop does not launch a projectile. It deploys -- an antimatter singularity that accumulates kinetic energy from everything that strikes it, the physics of annihilation applied to the principle that the most efficient weapon is one the enemy helps you build. Molecular Prime does not debuff. It rewrites -- the fundamental molecular structure of every entity in range altered to be significantly more reactive to force, the moment when the Ton-618 Dao reveals that the Molecular Empress was never fighting the enemy. She was preparing the medium.$doc$
where build_title = 'Ton-618';

update wf_user.my_frames
set
    cultivation_color    = '#E8E4D0',
    cultivation_school   = 'Cosmic Antimatter Council',
    cultivation_identity = 'Rift Sovereign',
    cultivation_art      = 'Rift Hybrid Dao of the Twin-Born Heir',
    cultivation_doctrine = $doc$Caliban is the only Warframe in the Cosmic Antimatter Council who holds simultaneous citizenship in the Ironclad Mountain Hall, because his cultivation practice is the meeting point of two traditions that should be mutually exclusive: Sentient adaptive resistance and Warframe combat capability. He is Erra's creation, the heir of twin kingdoms -- Sol and Tau, the Tenno civilization and the Sentient civilization -- and his Adaptive Armor is the architectural proof that the Rift Hybrid Dao's central teaching is correct: that the cultivator who can learn from incoming damage and restructure their defenses in real time has access to a form of durability that static armor values cannot reach. Fusion does not summon Conculysts and Battalysts. It calls family -- the Sentient kindred who recognize Caliban as the Twin-Born Heir, the half-Sentient who carries both bloodlines without being fully claimed by either. Razor Gyre does not deal damage. It expresses the hybrid nature -- Sentient energy and Warframe mechanics combining into a combat form that neither tradition could produce independently. The Rift Hybrid Dao teaches that the cultivator born between two worlds does not have to choose. The space between worlds is itself a cultivation ground.$doc$
where build_title = 'Rift Sovereign';

update wf_user.my_frames
set
    cultivation_color    = '#9ACD32',
    cultivation_school   = 'Cosmic Antimatter Council',
    cultivation_identity = 'Son of the Void',
    cultivation_art      = 'Void-Shattered Dao of the Three Voices',
    cultivation_doctrine = $doc$Xaku Prime is three Warframes who failed separately and succeeded together -- Xata, Lohk, and Fass/Ris, their fragments fused through Void exposure into something none of them was individually. The Void-Shattered Dao does not treat this as a tragedy. It treats it as the Cosmic Antimatter Council's most complete proof that the Void does not destroy; it recombines. Xata's Whisper does not add Void damage. It speaks -- the first of the Three Voices adding its frequency to the weapons of anyone in range, the Voidtongue language that Xaku Prime inherited from three different incomplete Warframes finding its first expression through projectiles. Grasp of Lohk does not steal weapons. It extends Lohk's reach across the Void boundary -- the second Voice manifesting as the capacity to unmake an enemy's offensive capability through dimensional contact. The Lost does not offer three separate abilities. It offers three perspectives -- Deny, Accuse, Gaze -- each one a different Void-sovereign technique from a different one of Xaku Prime's component sources. Xata's Whisper does not complete them. The Void completes them. The Son of the Void is the proof that the most powerful cultivator is not the one who is whole but the one who has learned what the fracture reveals.$doc$
where build_title = 'Son of the Void';

update wf_user.my_frames
set
    cultivation_color    = '#6A0DAD',
    cultivation_school   = 'Cosmic Antimatter Council',
    cultivation_identity = 'Psychic Empress',
    cultivation_art      = 'Mind Veil Dao of the Primordial Night',
    cultivation_doctrine = $doc$Nyx Prime's Greek lineage is Nyx, the primordial goddess of Night who was old before the Olympians were gods -- one of the first-generation cosmological forces whose presence even Zeus was reluctant to contest. The Cosmic Antimatter Council places her here because the Mind Veil Dao operates at the same scale: not tactical psychic manipulation but cosmological psychic saturation, the Primordial Night's influence spreading until it is the local reality rather than an effect applied to it. Mind Control does not dominate an enemy. It recruits from the Primordial Night's perspective -- the goddess who is old enough that every mind she enters was always, on some level, hers to enter. Psychic Bolts does not deal damage. It conducts a mass revelation: every target struck suddenly understands their own vulnerability at the deepest possible level, the Mind Veil pulling back to show them what they look like from the outside of their own skull. Chaos does not confuse enemies. It releases -- the Primordial Night's fundamental state, the condition that existed before order was imposed on the cosmos, briefly reinstalled in every mind in range. Absorb does not provide damage immunity. It completes the Psychic Empress's cultivation cycle: every attempt to damage her becomes part of her, the Primordial Night absorbing what is thrown against it and returning it as the darkness it always was.$doc$
where build_title = 'Psychic Empress';
